import json
d = json.load(open('artifacts/results/plan001/cross_benchmark_iv.json'))
out = {
    'top_level_keys': list(d.keys()),
    'cross_correlations': d['cross_correlations'],
    'summary': d['summary'],
}

# Reduced form: count significant keff results
rf_summary = {}
for k_size in ['K3', 'K5', 'K7']:
    if k_size in d.get('reduced_form', {}):
        rf = d['reduced_form'][k_size]
        sig_count = 0
        total_count = 0
        details = []
        for direction in rf:
            for cond_name, cond_data in rf[direction].items():
                if not cond_data.get('skipped', False):
                    total_count += 1
                    sig = cond_data.get('keff_p', 1) < 0.05
                    if sig:
                        sig_count += 1
                    details.append({
                        'key': f'{direction}/{cond_name}',
                        'keff_std_beta': round(cond_data.get('keff_std_beta', 0), 4),
                        'keff_p': cond_data.get('keff_p'),
                        'r_squared': round(cond_data.get('r_squared', 0), 4),
                        'n_panels': cond_data.get('n_panels'),
                    })
        rf_summary[k_size] = {
            'significant_keff': f'{sig_count}/{total_count}',
            'details': details
        }
out['reduced_form_summary'] = rf_summary

# 2SLS
if 'two_sls' in d:
    tsls = {}
    for k_size in ['K3', 'K5', 'K7']:
        if k_size in d['two_sls']:
            tsls_k = d['two_sls'][k_size]
            conds = {}
            for cond_name, cond_data in tsls_k.items():
                conds[cond_name] = {
                    'first_stage_F': cond_data.get('first_stage_F'),
                    'strong_instrument': cond_data.get('strong_instrument'),
                    'second_stage_beta': cond_data.get('second_stage_beta'),
                    'second_stage_p': cond_data.get('second_stage_p'),
                }
            tsls[k_size] = conds
    out['two_sls_summary'] = tsls

# Permutation
if 'permutation_test' in d:
    perm = {}
    for k_size in ['K3', 'K5', 'K7']:
        if k_size in d['permutation_test']:
            pk = d['permutation_test'][k_size]
            perm_details = {}
            for test_name, test_data in pk.items():
                perm_details[test_name] = {
                    'keff_max_p': test_data.get('keff_max_p'),
                    'eta_max_p': test_data.get('eta_max_p'),
                    'keff_fdr_p': test_data.get('keff_fdr_p'),
                    'eta_fdr_p': test_data.get('eta_fdr_p'),
                }
            perm[k_size] = perm_details
    out['permutation_summary'] = perm

print(json.dumps(out, indent=2))
"

